    if vt=='value': continue
    try: v=float(vt)
    except: continue
    vals.setdefault(tid,[]).append((t,v))
for k in vals: vals[k].sort()

zt={uri.split('#')[1]:tid for tid,(uri,cls) in info.items() if cls=='Zone_Air_Temperature_Sensor'}

def hourly_means(tid, start='2018-07-01', end='2019-01-01'):
    byh=defaultdict(list)
    for t,v in vals[tid]:
        if start<=t<end: byh[int(t[11:13])].append(v)
    return [statistics.mean(x) for x in byh.values()]

f3z01=hourly_means(zt['Zone_F3_Z01.Zone_Air_Temperature_Sensor'])
f3z02=hourly_means(zt['Zone_F3_Z02.Zone_Air_Temperature_Sensor'])
