    vals.setdefault(tid,[]).append((t,v))
for k in vals: vals[k].sort()

zt={uri.split('#')[1]:tid for tid,(uri,cls) in info.items() if cls=='Zone_Air_Temperature_Sensor'}
z01=dict(vals[zt['Zone_F3_Z01.Zone_Air_Temperature_Sensor']])
z03=dict(vals[zt['Zone_F3_Z03.Zone_Air_Temperature_Sensor']])
z05=dict(vals[zt['Zone_F3_Z05.Zone_Air_Temperature_Sensor']])

def window_stats(d1,d2, start, end, name=''):
    common=sorted(set(d1)&set(d2))
    common=[t for t in common if start<=t<end]
    if not common: return None
    diffs=[d1[t]-d2[t] for t in common]
    return (statistics.mean(diffs), statistics.stdev(diffs))

for win in [('2018-01-01','2018-07-01'), ('2018-07-01','2018-10-01'),('2018-10-01','2019-01-01')]:
    s,e=win
    r1=window_stats(z01,z03,s,e)
    r2=window_stats(z01,z05,s,e)
    print(win, "diff F3_Z01-F3_Z03: avg %.2f (std %.2f)"%(r1[0],r1[1]), "  diff F3_Z01-F3_Z05: avg %.2f (std %.2f)"%(r2[0],r2[1]))

# Now check correlation of F3_Z01 with F3_Z03 in two windows
def corr(d1,d2,s,e):
    common=sorted(t for t in set(d1)&set(d2) if s<=t<e)
    x=[d1[t] for t in common]; y=[d2[t] for t in common]
    mx=statistics.mean(x); my=statistics.mean(y)
    sx=statistics.stdev(x); sy=statistics.stdev(y)
    cov=sum((a-mx)*(b-my) for a,b in zip(x,y))/len(x)
    return cov/(sx*sy)
for win in [('2018-01-01','2018-07-01'), ('2018-07-01','2018-10-01'),('2018-10-01','2019-01-01')]:
    s,e=win
    print(win, "corr(F3_Z01,F3_Z03)=%.3f corr(F3_Z01,F3_Z05)=%.3f"%(corr(z01,z03,s,e),corr(z01,z05,s,e)))

